"""Complexity ratchet: no function may get more complex than the baseline allows.

Each function is measured for cyclomatic complexity (CCN) and nesting depth (the deepest stack of
control structures inside it). A function over a target (CCN above 7, nesting above 3) must be in
the baseline file, and may not exceed its baseline values; a baseline entry that is now within the
targets, measured lower, or gone must be removed or lowered, so the baseline only shrinks.

Usage:
  complexity.py BASELINE --files LIST [--update [--accept PATH::FUNCTION]...]
  complexity.py BASELINE --measurements CSV [--update [--accept PATH::FUNCTION]...]
  complexity.py BASELINE --compare-with OLD_BASELINE

--files measures every path listed in LIST (one per line) with lizard, which must be importable;
Python nesting is measured with the ast module instead, because lizard's count for Python carries
over from one function to the next. --measurements reads `path,function,ccn,nesting` rows instead
(used by the tests).

Each finding says how to resolve it:
  FAIL   a function is over a target and not in the baseline, or worse than its entry;
  STALE  an entry is better than recorded, within the targets, or its function is gone;
  MOVED  a function not in the baseline matches, no worse, a gone entry with the same name in
         another file (a moved or renamed file).
--update rewrites the baseline from the measurements. It records STALE and MOVED findings, and
refuses while a FAIL is left, unless --accept names that function (a reviewed exception) or the
baseline does not exist yet.

--compare-with reports, without failing, the entries of BASELINE that OLD_BASELINE did not have or
had lower (moves aside), in the log and in the GitHub job summary when $GITHUB_STEP_SUMMARY is set.

The baseline has one line per function over a target: path, function, CCN and nesting, separated
by tabs. Functions are keyed by path and name, never by line, so moving code inside a file does
not touch the baseline; functions that share a name in one file are compared worst with worst.
"""

from __future__ import annotations

import argparse
import ast
import collections
import csv
import os
import sys
from pathlib import Path
from typing import NamedTuple

CCN_TARGET = 7
NESTING_TARGET = 3

HEADER = f"""\
# Functions over the complexity targets (CCN above {CCN_TARGET}, nesting above {NESTING_TARGET}).
# Generated by make complexity-update; entries may only be lowered, removed or moved, except
# reviewed exceptions recorded with ACCEPT= and explained in their pull request.
# path\tfunction\tccn\tnesting
"""


class Measure(NamedTuple):
    ccn: int
    nesting: int


Key = tuple[str, str]
Table = dict[Key, list[Measure]]


def over_target(m: Measure) -> bool:
    return m.ccn > CCN_TARGET or m.nesting > NESTING_TARGET


def allowance(m: Measure) -> Measure:
    """What a baseline entry permits: its own values, never less than the targets."""
    return Measure(max(m.ccn, CCN_TARGET), max(m.nesting, NESTING_TARGET))


def fits(m: Measure, b: Measure) -> bool:
    allowed = allowance(b)
    return m.ccn <= allowed.ccn and m.nesting <= allowed.nesting


# ---- measuring ----

NESTING_NODES = (
    ast.If, ast.For, ast.AsyncFor, ast.While, ast.Try, ast.With, ast.AsyncWith, ast.Match,
) + ((ast.TryStar,) if hasattr(ast, "TryStar") else ())
SCOPES = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)


def python_nesting(path: str) -> dict[int, int]:
    """Nesting depth of each function in a Python file, by the line of its `def`."""
    tree = ast.parse(Path(path).read_text(encoding="utf-8"), filename=path)
    depths: dict[int, int] = {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            depths[node.lineno] = max((_depth(child, 0) for child in node.body), default=0)
    return depths


def _depth(node: ast.AST, depth: int, is_elif: bool = False) -> int:
    """Deepest control-structure stack under node; nested functions and classes count apart.

    An `elif` is the lone `If` in its parent's `orelse`; it sits at its parent's level.
    """
    if isinstance(node, SCOPES):
        return depth
    inner = depth + 1 if isinstance(node, NESTING_NODES) and not is_elif else depth
    elif_child = (
        node.orelse[0]
        if isinstance(node, ast.If) and len(node.orelse) == 1 and isinstance(node.orelse[0], ast.If)
        else None
    )
    return max(
        [inner]
        + [_depth(child, inner, child is elif_child) for child in ast.iter_child_nodes(node)]
    )


def measure_files(paths: list[str]) -> list[tuple[str, str, Measure]]:
    import lizard  # pinned in complexity.sh

    rows = []
    for path in paths:
        # A fresh analyzer per file: lizard's nesting count leaks from one file into the next.
        info = lizard.FileAnalyzer(lizard.get_extensions(["NS"]))(path)
        nesting = python_nesting(path) if path.endswith(".py") else None
        for f in info.function_list:
            if nesting is None:
                depth = f.max_nested_structures
            elif f.start_line in nesting:
                depth = nesting[f.start_line]
            else:
                sys.exit(f"complexity: {path}:{f.start_line}: lizard found the function {f.name} "
                         "but the ast module has no function starting on that line")
            rows.append((path, f.name, Measure(f.cyclomatic_complexity, depth)))
    return rows


def read_measurements(path: str) -> list[tuple[str, str, Measure]]:
    with open(path, newline="", encoding="utf-8") as fh:
        return [(r[0], r[1], Measure(int(r[2]), int(r[3]))) for r in csv.reader(fh) if r]


# ---- baseline ----

def table_of(rows: list[tuple[str, str, Measure]]) -> Table:
    table: Table = collections.defaultdict(list)
    for path, name, m in rows:
        table[(path, name)].append(m)
    for ms in table.values():
        ms.sort(reverse=True)
    return table


def group(rows: list[tuple[str, str, Measure]]) -> Table:
    return table_of([row for row in rows if over_target(row[2])])


def read_baseline(path: Path) -> Table:
    rows = []
    for number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if not line.strip() or line.startswith("#"):
            continue
        fields = line.split("\t")
        if len(fields) != 4 or not fields[2].isdigit() or not fields[3].isdigit():
            sys.exit(f"{path}:{number}: expected path, function, ccn and nesting separated by tabs, "
                     f"found {line!r}")
        rows.append((fields[0], fields[1], Measure(int(fields[2]), int(fields[3]))))
    return table_of(rows)


def write_baseline(path: Path, table: Table) -> None:
    lines = [f"{p}\t{name}\t{m.ccn}\t{m.nesting}\n"
             for (p, name), ms in sorted(table.items()) for m in ms]
    path.write_text(HEADER + "".join(lines), encoding="utf-8")


# ---- comparing ----

FAIL_KINDS = ("NEW", "WORSE")


class Finding(NamedTuple):
    kind: str  # NEW, WORSE (failures), BETTER, GONE (stale entries) or MOVED
    key: Key
    now: Measure | None
    before: Measure | None
    origin: Key | None = None  # MOVED: the gone baseline entry it matches


def compare(current: Table, baseline: Table, present: set[Key]) -> list[Finding]:
    """Every difference between the measurements over a target and the baseline.

    present holds every measured (path, function), over the targets or not; a baseline entry can
    only be the origin of a move when its function is absent from it.

    Functions that share a path and a name are paired by rank, worst with worst. That cannot tell
    which of them changed: if one gets worse while another gets better by as much, the pair reads
    as unchanged, and an entry can pass to a different function of that name. Such names are
    mostly per-type `fmt` or `new`, and each is still held to the worst value its name had in
    that file.
    """
    findings = []
    for key in sorted(set(current) | set(baseline)):
        now, before = current.get(key, []), baseline.get(key, [])
        for m, b in zip(now, before):
            if not fits(m, b):
                findings.append(Finding("WORSE", key, m, b))
            elif allowance(m) != allowance(b):
                findings.append(Finding("BETTER", key, m, b))
        findings += [Finding("NEW", key, m, None) for m in now[len(before):]]
        findings += [Finding("GONE", key, None, b) for b in before[len(now):]]
    return pair_moves(findings, present)


def pair_moves(findings: list[Finding], present: set[Key]) -> list[Finding]:
    """Turns a NEW finding and a GONE one with the same function name into one MOVED finding.

    The gone entry's function must no longer exist at its path (one simplified below the targets
    still does, so its entry stays STALE and the new function stays NEW), and the NEW function
    must be no worse than the entry. Among several candidates the tightest one is taken, so a
    small function never uses up a large entry another move needs.
    """
    gone = sorted((f for f in findings if f.kind == "GONE" and f.key not in present),
                  key=lambda f: allowance(f.before))
    used: set[int] = set()
    result = []
    for f in findings:
        if f.kind == "GONE":
            continue
        match = None
        if f.kind == "NEW":
            match = next((i for i, g in enumerate(gone) if i not in used
                          and g.key[1] == f.key[1] and fits(f.now, g.before)), None)
        if match is None:
            result.append(f)
        else:
            used.add(match)
            result.append(Finding("MOVED", f.key, f.now, gone[match].before, gone[match].key))
    result += [g for i, g in enumerate(gone) if i not in used]
    result += [f for f in findings if f.kind == "GONE" and f.key in present]
    return sorted(result, key=lambda f: (f.key, f.kind))


def describe(m: Measure | None) -> str:
    return f"CCN {m.ccn}, nesting {m.nesting}" if m else "-"


def accept_hint(key: Key) -> str:
    return ("simplify it, or, if it is a reviewed exception (flat per-variant dispatch such as a "
            "Display or kind match), record it with make complexity-update "
            f"ACCEPT='{key[0]}::{key[1]}' and say so in the pull request")


def message(f: Finding) -> str:
    where = f"{f.key[0]}: {f.key[1]}"
    if f.kind == "NEW":
        return (f"FAIL {where}: {describe(f.now)} is over the targets (CCN {CCN_TARGET}, nesting "
                f"{NESTING_TARGET}) and not in the baseline: {accept_hint(f.key)}")
    if f.kind == "WORSE":
        return (f"FAIL {where}: {describe(f.now)} is worse than the baseline's "
                f"{describe(f.before)}: {accept_hint(f.key)}")
    if f.kind == "BETTER":
        return (f"STALE {where}: {describe(f.now)} is better than the baseline's "
                f"{describe(f.before)}: lower its entry with make complexity-update")
    if f.kind == "GONE":
        return (f"STALE {where}: baseline entry {describe(f.before)} is now within the targets or "
                "the function is gone: remove it with make complexity-update")
    origin = f"{f.origin[0]}: {f.origin[1]}" if f.origin else "-"
    return (f"MOVED {where}: {describe(f.now)} matches the gone baseline entry {origin} "
            f"({describe(f.before)}): record the move with make complexity-update")


def summary(table: Table) -> str:
    by_language: dict[str, list[Measure]] = collections.defaultdict(list)
    for (path, _), ms in table.items():
        by_language[Path(path).suffix.lstrip(".")].extend(ms)
    parts = [f"{lang} {len(ms)} (max CCN {max(m.ccn for m in ms)}, "
             f"max nesting {max(m.nesting for m in ms)})"
             for lang, ms in sorted(by_language.items())]
    return ", ".join(parts) or "empty"


# ---- modes ----

def parse_accepted(values: list[str], findings: list[Finding]) -> set[Key]:
    failing = {f.key for f in findings if f.kind in FAIL_KINDS}
    accepted = set()
    for value in values:
        path, sep, name = value.rpartition("::")
        if not sep or (path, name) not in failing:
            sys.exit(f"complexity: --accept {value!r} names no function that is over the targets "
                     "and not in the baseline, or worse than its entry; write it as path::function "
                     "exactly as a FAIL line prints it")
        accepted.add((path, name))
    return accepted


def update(path: Path, current: Table, findings: list[Finding], accept: list[str]) -> int:
    accepted = parse_accepted(accept, findings)
    blocking = [f for f in findings if f.kind in FAIL_KINDS and f.key not in accepted]
    for f in findings:
        label = "ACCEPTED " if f.kind in FAIL_KINDS and f.key in accepted else ""
        print(f"complexity: {label}{message(f)}")
    if blocking and path.exists():
        print(f"complexity: the baseline was not updated: {len(blocking)} FAIL line(s) above, "
              "each saying how to resolve it")
        return 1
    write_baseline(path, current)
    print(f"complexity: wrote {path}: {summary(current)}")
    return 0


def check(baseline: Table, findings: list[Finding], measured: int) -> int:
    for f in findings:
        print(f"complexity: {message(f)}")
    if findings:
        print(f"complexity: {len(findings)} difference(s) from the baseline; each line above says "
              "how to resolve it")
        return 1
    print(f"complexity: ok, {measured} functions measured; baseline: {summary(baseline)}")
    return 0


def report_changes(new: Table, old: Table) -> int:
    """Logs the entries a baseline gained or raised against an older one; never fails.

    A baseline lists only functions over the targets, so an old entry counts as gone here when its
    function has no entry in the new baseline.
    """
    findings = compare(new, old, set(new))
    raised = [f for f in findings if f.kind in FAIL_KINDS]
    moved = [f for f in findings if f.kind == "MOVED"]
    if raised:
        print(f"::warning title=Complexity baseline::{len(raised)} entry(ies) added or raised; "
              "the pull request must say why each is a reviewed exception")
        body = "### Complexity baseline: entries added or raised\n\n"
        for f in raised:
            what = "added" if f.kind == "NEW" else f"raised from {describe(f.before)}"
            body += f"- `{f.key[0]}` `{f.key[1]}`: {describe(f.now)}, {what}\n"
        body += "\nEach must be a reviewed exception, explained in the pull request.\n"
    else:
        body = "### Complexity baseline: no entry added or raised\n"
    if moved:
        body += f"\n{len(moved)} entry(ies) moved with their files, no worse:\n\n"
        for f in moved:
            origin = f.origin[0] if f.origin else "-"
            body += f"- `{f.key[1]}`: `{origin}` → `{f.key[0]}`, {describe(f.now)}\n"
    print(body, end="")
    summary_path = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary_path:
        with open(summary_path, "a", encoding="utf-8") as fh:
            fh.write(body)
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("baseline", type=Path)
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--files", help="file listing the paths to measure, one per line")
    source.add_argument("--measurements", help="CSV of path,function,ccn,nesting")
    source.add_argument("--compare-with", type=Path, help="older baseline to report changes from")
    parser.add_argument("--update", action="store_true", help="rewrite the baseline")
    parser.add_argument("--accept", action="append", default=[], metavar="PATH::FUNCTION",
                        help="with --update, record this new or worse function on purpose")
    args = parser.parse_args()
    if args.accept and not args.update:
        parser.error("--accept needs --update")

    if args.compare_with:
        return report_changes(read_baseline(args.baseline), read_baseline(args.compare_with))
    if args.files:
        rows = measure_files(Path(args.files).read_text(encoding="utf-8").split())
    else:
        rows = read_measurements(args.measurements)
    current = group(rows)
    baseline = read_baseline(args.baseline) if args.baseline.exists() else {}
    findings = compare(current, baseline, {(path, name) for path, name, _ in rows})
    if args.update:
        return update(args.baseline, current, findings, args.accept)
    return check(baseline, findings, len(rows))


if __name__ == "__main__":
    sys.exit(main())
